    xa, xb = [ra[s] for s in seeds], [rb[s] for s in seeds]
    mean, t, ci = paired_t(xa, xb)
    wins = sum(y < x for x, y in zip(xa, xb))
    return {"n": len(seeds), "mean_diff": mean, "t": t, "ci": list(ci), "wins": wins}

