import math
from statistics import NormalDist


def runs_needed(sd_d, delta, alpha=0.05, power=0.8):
    z = NormalDist().inv_cdf
    n = ((z(1 - alpha / 2) + z(power)) * sd_d / delta) ** 2
    return math.ceil(n)

